#!/usr/bin/env bash
set -euo pipefail
umask 077
export PGPASSWORD
PGPASSWORD="$(cat /run/secrets/db_password)"
mkdir -p /backups
temporary="$(mktemp /backups/.ledger-backup.XXXXXX)"
trap 'rm -f -- "$temporary"' EXIT
pg_dump --format=custom --no-owner --no-acl | age --recipients-file /run/secrets/backup_recipients > "$temporary"
test -s "$temporary"
mv -- "$temporary" "/backups/ledger-$(date -u +%Y%m%dT%H%M%S)-${RANDOM}.dump.age"
# Only files generated by this script participate in seven-backup retention.
mapfile -t archives < <(find /backups -maxdepth 1 -type f -name 'ledger-*.dump.age' -printf '%f\n' | sort -r)
for ((index=7; index<${#archives[@]}; index++)); do rm -- "/backups/${archives[index]}"; done
touch /tmp/backup-success
printf 'backup complete\n'
